export interface WebGLSupport {
  available: boolean;
  version: 2 | 1 | null;
  reason: string | null;
}

export class WebGLUnavailableError extends Error {
  readonly support: WebGLSupport;

  constructor(support: WebGLSupport) {
    super(`WebGL is unavailable: ${support.reason ?? "unknown reason"}`);
    this.name = "WebGLUnavailableError";
    this.support = support;
  }
}

export const RIG_CONTEXT_ATTRIBUTES: WebGLContextAttributes = {
  alpha: true,
  antialias: true,
  preserveDrawingBuffer: true,
};

const CONTEXT_CANDIDATES: ReadonlyArray<readonly [string, 2 | 1, string]> = [
  ["webgl2", 2, "WebGL2RenderingContext"],
  ["webgl", 1, "WebGLRenderingContext"],
  ["experimental-webgl", 1, "WebGLRenderingContext"],
];

let cached: WebGLSupport | null = null;
let override: WebGLSupport | null = null;

function probe(): WebGLSupport {
  if (typeof document === "undefined") {
    return { available: false, version: null, reason: "no document" };
  }

  let reason: string | null = null;
  const canvas = document.createElement("canvas");

  const onCreationError = (event: Event) => {
    const message = (event as unknown as { statusMessage?: string }).statusMessage;
    if (message) reason = message;
  };
  canvas.addEventListener("webglcontextcreationerror", onCreationError, false);

  try {
    for (const [name, version, constructorName] of CONTEXT_CANDIDATES) {
      if (!(constructorName in window)) continue;

      let gl: unknown = null;
      try {
        gl = (canvas as any).getContext(name, RIG_CONTEXT_ATTRIBUTES);
      } catch (error) {
        reason = reason ?? String(error);
      }
      if (gl) {
        try {
          (gl as WebGLRenderingContext)
            .getExtension("WEBGL_lose_context")
            ?.loseContext();
        } catch {
          /* best effort */
        }
        return { available: true, version, reason: null };
      }
    }
  } finally {
    canvas.removeEventListener("webglcontextcreationerror", onCreationError, false);
    canvas.width = 0;
    canvas.height = 0;
  }

  return { available: false, version: null, reason: reason ?? "no WebGL context" };
}

export function getWebGLSupport(): WebGLSupport {
  if (override) return override;
  if (!cached) cached = probe();
  return cached;
}

export function setWebGLSupportOverride(support: WebGLSupport | null): void {
  override = support;
}

export function isWebGLAvailable(): boolean {
  return getWebGLSupport().available;
}

export function assertWebGLAvailable(): void {
  const support = getWebGLSupport();
  if (!support.available) throw new WebGLUnavailableError(support);
}

export function resetWebGLSupportCache(): void {
  cached = null;
}
